WITH ctx AS MATERIALIZED(SELECT set_config('app.current_company_id','1',true) cid), live AS MATERIALIZED(SELECT id,voucher_date FROM vouchers WHERE company_id=(SELECT cid::int FROM ctx) AND deleted_at IS NULL AND optional=false),ee AS MATERIALIZED(SELECT voucher_id,ledger_account_id,debit_amount,credit_amount FROM voucher_entries WHERE company_id=(SELECT cid::int FROM ctx)),june AS MATERIALIZED(SELECT COALESCE(SUM(ee.debit_amount),0) dr,COALESCE(SUM(ee.credit_amount),0) cr FROM ee JOIN live v ON v.id=ee.voucher_id WHERE ee.ledger_account_id=1007 AND v.voucher_date>=DATE '2026-06-01' AND v.voucher_date<DATE '2026-07-01'),a AS MATERIALIZED(SELECT ee.ledger_account_id,SUM(ee.debit_amount-ee.credit_amount) net FROM ee JOIN live v ON v.id=ee.voucher_id WHERE ee.ledger_account_id IN(1007,1021,1022,4282) GROUP BY ee.ledger_account_id),s AS MATERIALIZED(SELECT (SELECT dr FROM june) june_debit,(SELECT cr FROM june) june_credit,(SELECT net FROM a WHERE ledger_account_id=1007) expense_balance_dr,(SELECT net FROM a WHERE ledger_account_id=1021) accrued_balance_dr,(SELECT net FROM a WHERE ledger_account_id=1022) prepaid_balance_dr,(SELECT net FROM a WHERE ledger_account_id=4282) timing_balance_dr,(SELECT COUNT(*) FROM vouchers WHERE company_id=1 AND id IN(8565,8586,8790,17511) AND deleted_at IS NOT NULL) superseded,(SELECT COUNT(*) FROM audit_log WHERE company_id=1 AND user_id='system:hadi-june-2026-original-sources-part1-20261110' AND action='repair') repair_audits,(SELECT COUNT(*) FROM voucher_entries WHERE company_id=1 AND id=30202 AND voucher_id=8789 AND ledger_account_id=1021 AND debit_amount=4200) payment_8789_correct,(SELECT COUNT(*) FROM voucher_entries WHERE company_id=1 AND id=30535 AND voucher_id=8870 AND ledger_account_id=1021 AND debit_amount=10500) payment_8870_correct,(SELECT COUNT(*) FROM voucher_entries WHERE company_id=1 AND voucher_id=8870 AND ledger_account_id=1022 AND debit_amount=21000 AND credit_amount=0) prepaid_line_added,(SELECT COUNT(*) FROM voucher_entries WHERE company_id=1 AND id IN(30203,30536) AND ledger_account_id=112 AND ((id=30203 AND credit_amount=4200 AND debit_amount=0) OR(id=30536 AND credit_amount=31500 AND debit_amount=0))) original_safe_counterparts_unchanged) SELECT CASE WHEN june_debit=127550 AND june_credit=86600 AND expense_balance_dr=434350 AND accrued_balance_dr=-18000 AND prepaid_balance_dr=7000 AND timing_balance_dr=0 AND superseded=4 AND repair_audits=6 AND payment_8789_correct=1 AND payment_8870_correct=1 AND prepaid_line_added=1 AND original_safe_counterparts_unchanged=2 THEN 'PASS JUNE PART 1' ELSE 'NOT YET CORRECTED / FAILED - DO NOT RUN ANOTHER SCRIPT' END result,s.* FROM s;
